def parse_ts(obj):
    for k in ("ts","timestamp","created_at","time","received_at"):
        v = obj.get(k)
        if not v: continue
        if isinstance(v,(int,float)):
            # ms or s
            if v > 1e12: v = v/1000
            return datetime.fromtimestamp(v, tz=timezone.utc).astimezone(BJ)
        s=str(v)
        for fmt in ("%Y-%m-%d %H:%M:%S","%Y-%m-%dT%H:%M:%S%z","%Y-%m-%dT%H:%M:%S.%f%z","%Y-%m-%dT%H:%M:%SZ","%Y-%m-%dT%H:%M:%S"):
